package com.wheelwright.evidence.v2.portfolio;
import com.fasterxml.jackson.databind.node.*;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.util.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;import static org.assertj.core.api.Assertions.*;
class PortfolioBrokerBasisPayoffTest {
 static ObjectNode structure(String shares,String stockCost,String callCost){
  var c=PortfolioShareCallShapeTest.fixture(shares,"100","1");((ObjectNode)c.at("/composition/children/1/terms")).put("strike","15");int i=0;for(var leaf:leaves(c.path("composition"))){var cost=i++==0?stockCost:callCost;if(cost!=null){var e=(ObjectNode)leaf.path("economics");e.set("reportedCostBasis",metric(new BigDecimal(cost),"MONEY","USD",null,"FIDELITY_REPORTED_WHOLE_HOLDING_COST_BASIS","QUALIFIED",array(),"HELD_INVENTORY"));e.put("reportedBasisWholeQuantity",true);}}return c;
 }
 static ObjectNode reference(ObjectNode c){return PortfolioMath.brokerBasisPayoff(c,PortfolioMath.terminalPayoff(c,PortfolioShareCallShapeTest.now));}
 static BigDecimal value(ObjectNode p,String price){var x=new BigDecimal(price);for(var s:p.at("/geometry/segments")){var hi=number(s.path("upper"));if(x.compareTo(number(s.path("lower")))>=0&&(hi==null||x.compareTo(hi)<=0))return x.multiply(number(s.path("slope"))).add(number(s.path("intercept")));}throw new AssertionError();}
 @Test void realSourceAmountsHaveDistinctEstimateAndExactRootsWithoutOpeningClaims(){var c=structure("100","1484","14.34");var p=reference(c);assertThat(p.at("/geometry/valueKind").asText()).isEqualTo("ESTIMATED_PL");assertThat(p.at("/geometry/breakEvenPrices/0").asText()).isEqualTo("14.6966");assertThat(p.at("/geometry/financialReference/maximumProfit").asText()).isEqualTo("30.34");for(var pair:List.of(new String[]{"12.4","-229.66"},new String[]{"14.70","0.34"},new String[]{"15","30.34"},new String[]{"16","30.34"}))assertThat(value(p,pair[0])).isEqualByComparingTo(pair[1]);var e=PortfolioMath.evaluate(c,Map.of(),PortfolioShareCallShapeTest.now);assertThat(e.at("/openingCashFlow/value").isNull()).isTrue();assertThat(e.at("/grossUnrealizedPl/value").isNull()).isTrue();assertThat(e.at("/payoff/geometry/valueKind").asText()).isEqualTo("TERMINAL_VALUE");}
 @Test void missingEitherCostCannotCreateProfitReference(){for(var costs:List.of(new String[]{null,"14.34"},new String[]{"1484",null})){var p=reference(structure("100",costs[0],costs[1]));assertThat(p.at("/geometry/valueKind").asText()).isEqualTo("TERMINAL_VALUE");assertThat(p.at("/geometry/breakEvenPrices")).isEmpty();}}
 @Test void zeroCapAndNegativeCapNeverGainGreenProfit(){for(String basis:List.of("1514.34","1600")){var p=reference(structure("100",basis,"14.34"));var e=obj();e.set("payoff",p);PortfolioPayoffPlot.apply(e);assertThat(p.at("/geometry/financialRegions")).allMatch(r->r.path("kind").asText().equals("LOSS"));if(basis.equals("1514.34"))assertThat(p.at("/geometry/breakEvenPrices/0").asText()).isEqualTo("15");else assertThat(p.at("/geometry/breakEvenPrices")).isEmpty();}}
 @Test void partialCoverageRetainsUncappedShortTailRatherThanCoveredTemplate(){var p=reference(structure("50","742","14.34"));assertThat(p.at("/geometry/segments/1/slope").asText()).isEqualTo("-50");assertThat(value(p,"40").signum()).isNegative();}
 @Test void adjustedContractCannotBePromotedByKnownCosts(){var c=structure("100","1484","14.34");((ObjectNode)c.at("/composition/children/1/terms")).put("adjustment","ADJUSTED");assertThat(reference(c).path("status").asText()).isNotEqualTo("QUALIFIED");}
 @Test void wrongCurrencyOrPartialBasisRefused(){for(String field:List.of("currency","reportedBasisWholeQuantity")){var c=structure("100","1484","14.34");var e=(ObjectNode)c.at("/composition/children/1/economics");if(field.equals("currency"))((ObjectNode)e.path("reportedCostBasis")).put("currency","EUR");else e.put(field,false);assertThat(reference(c).at("/geometry/valueKind").asText()).isEqualTo("TERMINAL_VALUE");}}
 @Test void regionsAndSpotAreValuesOfTheSameFunctionAndIgnoreRegime(){var p=reference(structure("100","1484","14.34"));var e=obj();e.set("payoff",p);e.set("spot",metric(new BigDecimal("12.4"),"PRICE","USD","2026-10-27T16:00:00Z","SOURCE","QUALIFIED",array()));PortfolioPayoffPlot.apply(e);assertThat(p.at("/geometry/spotPoint/value").asText()).isEqualTo("-229.66");assertThat(p.at("/geometry/financialRegions")).anyMatch(r->r.path("kind").asText().equals("LOSS")).anyMatch(r->r.path("kind").asText().equals("PROFIT"));for(var region:p.at("/geometry/financialRegions"))for(var point:region.path("points"))if(number(point.path("value")).signum()!=0)assertThat(number(point.path("value"))).isEqualByComparingTo(value(p,point.path("price").asText()));}
 @Test void historicalOpeningsRollsReopensAndRegimeCannotRedefineWholeHoldingReference(){var c=structure("100","1484","14.34");var expected=reference(c).path("geometry").deepCopy();for(String regime:List.of("Income Wheel","Growth Wheel","UNKNOWN")){c.put("operatingRegime",regime);c.set("history",array().add(obj().put("opening","ambiguous duplicate").put("priorCallNet","51.34").put("closeDebit","17.01")).add(obj().put("opening","shares closed and reopened")));assertThat(reference(c).path("geometry")).isEqualTo(expected);var ordinary=PortfolioMath.evaluate(c,Map.of(),PortfolioShareCallShapeTest.now);assertThat(ordinary.at("/timeline/openedAt").isNull()).isTrue();assertThat(ordinary.at("/openingCashFlow/value").isNull()).isTrue();}}
 @Test void rationalBreakEvenKeepsExactPriceAndBackendOwnedDisplayMarker(){var c=structure("300","4444","43.34");((ObjectNode)c.at("/composition/children/1")).put("quantity","3");var p=reference(c);assertThat(p.at("/geometry/breakEvenPrices/0/numerator").asText()).isEqualTo("220033");assertThat(p.at("/geometry/breakEvenPrices/0/denominator").asText()).isEqualTo("15000");var e=obj();e.set("payoff",p);PortfolioPayoffPlot.apply(e);assertThat(p.at("/geometry/breakEvenMarkers/0/approximate").asBoolean()).isTrue();assertThat(p.at("/geometry/breakEvenMarkers/0/label").asText()).isEqualTo("≈14.6689");assertThat(number(p.at("/geometry/breakEvenMarkers/0/price"))).isBetween(new BigDecimal("14.6688"),new BigDecimal("14.6690"));}
}
